/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Numbers
 *   Functions: source, saved, propose, flags
 *   Constants: none
 * Tests
 *   - the proposal reads every position the server reads, with the same rest, and is accepted exactly where the server's guard accepts the titles
 *   - each row names what stops the proposal: no position, the other form, a repeated or earlier position, a lone unpadded one, while a skipped number only notes a gap
 *   - a saved number that disagrees with its title, or several discs without a captured Disc Number, propose nothing for the Album
 *   - an accepted proposal fills only empty saved numbers, Disc Numbers only from Disc and Track positions, and starts selected only for those
 *   - each number cell fills, keeps, equals or replaces the stored value, and a Disc cell exists only where the review captured one
 *   - the cleanup removes exactly the position from titles still as captured, only for an accepted proposal, and never touches an edited title
 *   - the selection defaults carry every number an accepted Disc and Track proposal gives, the same once any number is saved, and each cleaned title with the numbers it needs
 *   - turning the cleanup off restores only the titles it wrote; when none is known, saved cleaned titles and never an unsaved edit
 *   - a 44-track Album on three discs proposes every Disc and Track Number, and one mistyped title stops it while naming only its own row
 * @end-catalog */

/**
 * The review's title proposal without rendering: per-row flags and the guard they make, the numbers it proposes and how each number
 * cell compares with the catalog, the optional title cleanup, the defaults it gives the Update selection, a 44-track Album on three
 * discs, and parity with the server's own position reader (src/administration/lookup/lookupTitlePositions.ts), imported here so the
 * server's test table runs against both. Every title is synthetic or a common song-title shape.
 */
import { leadingTitlePosition, leadingTitlePositions } from '../../../../src/administration/lookup/lookupTitlePositions';
import { longAlbumDiscs, longAlbumReview } from './catalogReviewLookupFixtures.testSupport';
import { proposalCells, titleCleanup, titleDefaults, titleProposal, toggleCleanup, withTitleProposal, type TitleProposalFlag } from './catalogReviewProposal';
import { titleLeadingPosition } from './reviewLookupStatus';

/** A stored Disc and Track Number; an undefined Disc Number was never captured. */
type Numbers = [number | null | undefined, number | null];
/** Source tracks with `titles` and the stored numbers given (empty by default; an undefined Disc Number was never captured). */
const source = (titles: readonly string[], numbers: readonly Numbers[] = []) => titles.map((title, index) => ({ slotId: `slot-${index + 1}`, title,
  ...(numbers[index]?.[0] === undefined && numbers[index] ? {} : { discNumber: numbers[index]?.[0] ?? null }), trackNumber: numbers[index]?.[1] ?? null }));
/** The saved draft of those tracks: their titles, with `numbers` where given, else the stored ones. */
const saved = (tracks: ReturnType<typeof source>, numbers: readonly [number | null, number | null][] = []) => tracks.map((track, index) => ({ slotId: track.slotId, title: track.title,
  discNumber: numbers[index] ? numbers[index][0] : track.discNumber ?? null, trackNumber: numbers[index] ? numbers[index][1] : track.trackNumber }));
/** The proposal of `titles` over a saved draft equal to the stored numbers. */
const propose = (titles: readonly string[], numbers: readonly Numbers[] = []) => { const tracks = source(titles, numbers); return titleProposal(tracks, saved(tracks)); };
/** Each row's flags in that proposal. */
const flags = (titles: readonly string[], numbers: readonly Numbers[] = []) => propose(titles, numbers).rows.map(row => row.flags);
const none: TitleProposalFlag[] = [];

test('the proposal reads every position the server reads, with the same rest, and is accepted exactly where the server\'s guard accepts the titles', () => {
  // The rows of test/administration/lookupTitlePositions.test.ts, then titles around its edges.
  const titles = ['1-01 Yorugaonokokuhaku(Live)', '1.01.雪の華', '1.01. 創生(Instrumental)', '01 X', '01 - X', '01.X', '001 X', ' 01  X', '1-01 - X', '1-01. X', '99-999 X',
    '2-12 Synthetic  Song ', '7 Rings', '01 . X', '01 – X', '1-01 — X', '01 ...Baby One More Time', '01 -X', '100-01 X', '1000 X', '0 X', '1-0 X', '0-1 X', '01', '01.',
    '01X', '01-X', '01_X', '12) X', '１．０１．X', 'X', '1999 X', 'Room404', '7', `01 ${'x'.repeat(1022)}`, `01 ${'x'.repeat(1021)}`, 'Disc2-03 X', '01 - 序曲', '1.5 Seconds',
    '1-2 Punch', '1.21 Gigawatts', '1-01X 2', '1.Song', '2-005 A', '00-01 X', '1-1000 X', '\t02　X', ''];
  for (const title of titles) {
    const server = leadingTitlePosition(title);
    expect(titleLeadingPosition(title), JSON.stringify(title)).toEqual(server);
  }
  const albums = [['1-01 A', '1-02 B'], ['1-01 A', '2-01 B'], ['1-01 A', '1.02.B', '1-03 - C'], ['01 A', '02.B', '03 - C'], ['1.01.雪の華', '1.02.WILL', '1.03.彩恋 ～SAI_REN～'],
    ['01 A', '1-02 B'], ['1-02 A', '03 B'], ['1-01 A', '02 B', '1-03 C'], ['2-01 A', '05 B'], ['01 A', '01 B'], ['02 A', '01 B'], ['1-02 A', '1-02 B'], ['7 Rings', 'thank u, next'],
    ['7 Rings', '99 Luftballons', '24 Hours'], ['Room404', 'Room405'], [], ['01 A', 'B'], ['1-01 A'], ['1.01.雪の華'], ['2-005 A'], ['7 Rings'], ['01 A'], ['01. A'], ['Room404'],
    ['1.5 Seconds'], ['1-2 Punch'], ['1.21 Gigawatts'], ['3.14 Pi'], ['2.5 Something'], ['1-5 A'], ['1-12 A'], ['24 Hours', '99 Luftballons'], ['1-01 A', '1-03 B'],
    ['01 - 序曲', '02 - 終曲'], ['1999 X', '2000 Y'], ['01 A', '1999 X'], ['1-01 A', '1-01 B', '1-02 C'], ['1-02 A', '1-01 B', '1-03 C'], ['3-01 A', '1-02 B'], ['1-03 A', '2-01 B', '2-02 C']];
  for (const album of albums) {
    const server = leadingTitlePositions(album), proposal = propose(album);
    expect(proposal.accepted, JSON.stringify(album)).toBe(server !== null);
    if (server) expect(proposal.rows.map(row => row.position), JSON.stringify(album)).toEqual(server);
  }
});

test('each row names what stops the proposal: no position, the other form, a repeated or earlier position, a lone unpadded one, while a skipped number only notes a gap', () => {
  expect(flags(['1-01 A', '1999 X', 'Disc2-03 B', 'Untitled'])).toEqual([none, ['noPosition'], ['noPosition'], ['noPosition']]);
  // Partial prefixes: some titles carry a position and some do not (the third row also skips Track 2).
  expect(flags(['01 A', 'B', '03 C'])).toEqual([none, ['noPosition'], ['gap']]);
  // The form most rows take is the Album's; a row of the other form is marked, also when it comes first.
  expect(propose(['05 A', '1-02 B', '1-03 C'])).toMatchObject({ form: 'discTrack', accepted: false });
  expect(flags(['05 A', '1-02 B', '1-03 C'])).toEqual([['formMismatch'], ['notIncreasing'], none]);
  expect(flags(['1-01 A', '1-02 B', '03 C'])).toEqual([none, none, ['formMismatch']]);
  expect(flags(['1-01 A', '1-02 B', '1-02 C', '1-01 D'])).toEqual([none, none, ['duplicate'], ['duplicate']]);
  expect(flags(['1-02 A', '1-01 B', '1-03 C'])).toEqual([none, ['notIncreasing'], none]);
  expect(flags(['2-01 A', '1-09 B'])).toEqual([none, ['notIncreasing']]);
  // A missing Disc Number counts as Disc 1, as on the Album page.
  expect(flags(['01 A', '1-01 B', '1-02 C'])).toEqual([['formMismatch'], ['duplicate'], none]);
  for (const title of ['01 A', '7 Rings', '1-1 A', '1-2 Punch', '1.5 Seconds']) expect(flags([title]), title).toEqual([['loneTrackOnly']]);
  for (const title of ['1-01 A', '1.01.雪の華', '2-005 A']) expect(propose([title]), title).toMatchObject({ accepted: true, rows: [{ flags: none }] });
  expect(flags(['1999 Synthetic'])).toEqual([['noPosition']]);
  const gap = propose(['1-01 A', '1-03 B', '2-01 C', '2-05 D']);
  expect([gap.accepted, gap.rows.map(row => row.flags)]).toEqual([true, [none, ['gap'], none, ['gap']]]);
  expect(propose([])).toEqual({ form: null, accepted: false, rows: [], count: 0, preselected: false });
  expect(propose(['A', 'B'])).toMatchObject({ form: null, accepted: false, count: 0 });
});

test('a saved number that disagrees with its title, or several discs without a captured Disc Number, propose nothing for the Album', () => {
  expect(flags(['01 A', '02 B'], [[null, 5], [null, null]])).toEqual([['disagrees'], none]);
  expect(flags(['1-01 A', '1-02 B'], [[2, null], [null, null]])).toEqual([['disagrees'], none]);
  // A Track Number alone says nothing about the Disc Number, so a saved one never disagrees with it.
  expect(propose(['01 A', '02 B'], [[2, null], [null, null]])).toMatchObject({ accepted: true, form: 'track' });
  const disagreeing = propose(['1-01 A', '1-02 B', '1-03 C'], [[null, null], [null, 7], [null, null]]);
  expect([disagreeing.accepted, disagreeing.count, disagreeing.rows.map(row => row.proposed)]).toEqual([false, 0, [{}, {}, {}]]);
  // The saved draft decides, not the stored value: a member saved at its title's position agrees even where the catalog stored another.
  const tracks = source(['01 A', '02 B'], [[null, 9], [null, null]]);
  expect(titleProposal(tracks, saved(tracks, [[null, 1], [null, null]])).accepted).toBe(true);
  // A legacy review never captured Disc Numbers: titles on several discs propose nothing, titles on one disc propose Track Numbers only.
  const legacy: Numbers[] = [[undefined, null], [undefined, null]];
  expect(flags(['1-01 A', '2-01 B'], legacy)).toEqual([['discNotCaptured'], ['discNotCaptured']]);
  expect(propose(['1-01 A', '1-02 B'], legacy).rows.map(row => row.proposed)).toEqual([{ trackNumber: 1 }, { trackNumber: 2 }]);
});

test('an accepted proposal fills only empty saved numbers, Disc Numbers only from Disc and Track positions, and starts selected only for those', () => {
  const both = propose(['1.01.雪の華', '1.02.WILL', '1.03.彩恋 ～SAI_REN～']);
  expect([both.form, both.accepted, both.preselected, both.count]).toEqual(['discTrack', true, true, 3]);
  expect(both.rows.map(row => [row.proposed, row.position?.rest])).toEqual([[{ discNumber: 1, trackNumber: 1 }, '雪の華'], [{ discNumber: 1, trackNumber: 2 }, 'WILL'],
    [{ discNumber: 1, trackNumber: 3 }, '彩恋 ～SAI_REN～']]);
  // "01 - 序曲" gives a Track Number alone: proposed, never selected by default, and no Disc Number.
  const track = propose(['01 - 序曲', '02 - 終曲']);
  expect([track.form, track.accepted, track.preselected, track.rows.map(row => row.proposed)]).toEqual(['track', true, false, [{ trackNumber: 1 }, { trackNumber: 2 }]]);
  // A saved number is kept; nothing left to fill proposes nothing.
  expect(propose(['1-01 A', '1-02 B'], [[1, 1], [null, null]]).rows.map(row => row.proposed)).toEqual([{}, { discNumber: 1, trackNumber: 2 }]);
  expect(propose(['1-01 A', '1-02 B'], [[1, 1], [1, 2]])).toMatchObject({ accepted: true, count: 0 });
  // The known limit, as on the server: titles that all start with increasing numbers read as Track positions, which stay unselected.
  expect(propose(['24 Hours', '99 Luftballons'])).toMatchObject({ accepted: true, preselected: false, form: 'track' });
});

test('each number cell fills, keeps, equals or replaces the stored value, and a Disc cell exists only where the review captured one', () => {
  const tracks = source(['1-01 A', '1-02 B', '1-03 C', '1-04 D'], [[null, 1], [1, null], [null, null], [undefined, null]]), proposal = titleProposal(tracks, saved(tracks));
  const resulting = withTitleProposal({ album: {} as never, tracks: saved(tracks) }, proposal, false).tracks;
  expect(proposalCells(proposal, tracks, resulting)).toEqual({ 'slot-1': { discNumber: 'fill', trackNumber: 'same' }, 'slot-2': { discNumber: 'same', trackNumber: 'fill' },
    'slot-3': { discNumber: 'fill', trackNumber: 'fill' }, 'slot-4': { discNumber: null, trackNumber: 'fill' } });
  // An administrator's number replacing a stored one, or clearing it, is an overwrite; an empty cell left empty is none.
  const edited = resulting.map(track => track.slotId === 'slot-1' ? { ...track, trackNumber: 9 } : track.slotId === 'slot-2' ? { ...track, discNumber: null } : track.slotId === 'slot-3' ? { ...track, discNumber: null } : track);
  expect(proposalCells(proposal, tracks, edited)).toMatchObject({ 'slot-1': { trackNumber: 'overwrite' }, 'slot-2': { discNumber: 'overwrite' }, 'slot-3': { discNumber: 'none' } });
  // Where nothing is accepted, a stored value is kept rather than equal to a title.
  const stored = source(['01 A', 'B'], [[null, 1], [null, null]]), rejected = titleProposal(stored, saved(stored));
  expect(proposalCells(rejected, stored, saved(stored))).toEqual({ 'slot-1': { discNumber: 'none', trackNumber: 'keep' }, 'slot-2': { discNumber: 'none', trackNumber: 'none' } });
});

test('the cleanup removes exactly the position from titles still as captured, only for an accepted proposal, and never touches an edited title', () => {
  const tracks = source(['1.01.雪の華', '1.02. WILL', '1-03 -  彩恋  ～SAI_REN～']), proposal = titleProposal(tracks, saved(tracks));
  expect(titleCleanup(proposal, tracks)).toEqual({ 'slot-1': '雪の華', 'slot-2': 'WILL', 'slot-3': '彩恋 ～SAI_REN～' });
  const edited = tracks.map(track => track.slotId === 'slot-2' ? { ...track, title: 'WILL (edited)' } : track);
  expect(titleCleanup(proposal, edited)).toEqual({ 'slot-1': '雪の華', 'slot-3': '彩恋 ～SAI_REN～' });
  expect(titleCleanup(propose(['1-01 A', 'B']), source(['1-01 A', 'B']))).toEqual({});
  // Written into a draft with the proposed numbers; off, the titles stay; a number the draft already has is never replaced.
  const draft = { album: {} as never, tracks: saved(tracks, [[null, null], [1, 2], [null, null]]) };
  expect(withTitleProposal(draft, proposal, true).tracks.map(track => [track.title, track.discNumber, track.trackNumber])).toEqual([['雪の華', 1, 1], ['WILL', 1, 2], ['彩恋 ～SAI_REN～', 1, 3]]);
  expect(withTitleProposal(draft, proposal, false).tracks.map(track => track.title)).toEqual(tracks.map(track => track.title));
});

test('the selection defaults carry every number an accepted Disc and Track proposal gives, the same once any number is saved, and each cleaned title with the numbers it needs', () => {
  const tracks = source(['1-01 A', '1-02 B'], [[null, null], [undefined, null]]);
  const defaults = titleDefaults(tracks, saved(tracks));
  expect([...defaults.numbers]).toEqual([['track:slot-1:trackNumber', 1], ['track:slot-1:discNumber', 1], ['track:slot-2:trackNumber', 2]]);
  expect([...defaults.titles]).toEqual([['track:slot-1:title', { title: 'A', numbers: ['discNumber', 'trackNumber'] }], ['track:slot-2:title', { title: 'B', numbers: ['trackNumber'] }]]);
  // Saved with the proposed numbers, or with a number of the administrator's own that disagrees with its title, the defaults stay.
  for (const numbers of [[[1, 1], [null, 2]], [[1, 1], [null, 5]], [[2, 9], [null, 2]]] as [number | null, number | null][][]) {
    const after = titleDefaults(tracks, saved(tracks, numbers));
    expect([[...after.numbers], [...after.titles]], JSON.stringify(numbers)).toEqual([[...defaults.numbers], [...defaults.titles]]);
  }
  // A stored number that disagrees with its title stops them, as it stops the proposal.
  const disagreeing = source(['1-01 A', '1-02 B'], [[null, 3], [undefined, null]]);
  expect(titleDefaults(disagreeing, saved(disagreeing)).titles.size).toBe(0);
  // Corrected and saved, the proposal the table shows over the saved draft gives them as the table does.
  const corrected = titleDefaults(disagreeing, saved(disagreeing, [[null, 1], [null, null]]));
  expect([[...corrected.numbers], corrected.titles.size]).toEqual([[...defaults.numbers], 2]);
  // Where the review captured no Disc Number, the saved one (lookup's, never the administrator's) is what the guard reads.
  const uncaptured = source(['1-01 A', '2-01 B'], [[undefined, null], [undefined, null]]);
  expect(titleDefaults(uncaptured, saved(uncaptured)).titles.size).toBe(0);
  expect([...titleDefaults(uncaptured, saved(uncaptured, [[1, null], [2, null]])).numbers]).toEqual([['track:slot-1:trackNumber', 1], ['track:slot-2:trackNumber', 1]]);
  // Track Numbers alone start nothing selected but can still be cleaned; nothing accepted gives nothing.
  const trackOnly = source(['01 - 序曲', '02 - 終曲']), plain = titleDefaults(trackOnly, saved(trackOnly));
  expect([plain.numbers.size, [...plain.titles.values()]]).toEqual([0, [{ title: '序曲', numbers: ['trackNumber'] }, { title: '終曲', numbers: ['trackNumber'] }]]);
  const rejected = source(['01 A', '1999 X']), nothing = titleDefaults(rejected, saved(rejected));
  expect([nothing.numbers.size, nothing.titles.size]).toEqual([0, 0]);
});

test('turning the cleanup off restores only the titles it wrote; when none is known, saved cleaned titles and never an unsaved edit', () => {
  const tracks = source(['1-01 A', '1-02 B', '1-03 C']), proposal = titleProposal(tracks, saved(tracks));
  const base = { album: {} as never, tracks: saved(tracks).map(track => ({ ...track, artists: [] })) }, typed = { tracks: { 'slot-2': { title: 'B' } } };
  const on = toggleCleanup(proposal, base, typed, true);
  expect([on.edits.tracks, on.keys, on.cleaned]).toEqual([{ 'slot-2': { title: 'B' }, 'slot-1': { title: 'A' }, 'slot-3': { title: 'C' } },
    ['track:slot-1:title', 'track:slot-3:title'], ['slot-1', 'slot-3']]);
  const off = toggleCleanup(proposal, base, on.edits, false, on.cleaned);
  expect([off.edits.tracks, off.keys, off.cleaned]).toEqual([{ 'slot-2': { title: 'B' }, 'slot-1': {}, 'slot-3': {} }, [], []]);
  // Saved cleaned (the page's record of them lost), turning it off restores them as edits, still leaving the typed title alone.
  const savedClean = { ...base, tracks: base.tracks.map(track => track.slotId === 'slot-2' ? track : { ...track, title: track.title.slice(5) }) };
  expect(toggleCleanup(proposal, savedClean, typed, false).edits.tracks).toEqual({ 'slot-2': { title: 'B' }, 'slot-1': { title: '1-01 A' }, 'slot-3': { title: '1-03 C' } });
});

test('a 44-track Album on three discs proposes every Disc and Track Number, and one mistyped title stops it while naming only its own row', () => {
  const item = longAlbumReview(), proposal = titleProposal(item.source.tracks, item.draft.tracks);
  expect([proposal.form, proposal.accepted, proposal.preselected, proposal.count, proposal.rows.length]).toEqual(['discTrack', true, true, 44, 44]);
  expect(proposal.rows.every(row => row.flags.length === 0)).toBe(true);
  const expected = longAlbumDiscs.flatMap((count, disc) => Array.from({ length: count }, (_, index) => ({ discNumber: disc + 1, trackNumber: index + 1 })));
  expect(proposal.rows.map(row => row.proposed)).toEqual(expected);
  expect(proposal.rows.map(row => row.position!.rest)).toEqual(item.source.tracks.map((_, index) => `Synthetic long song ${index + 1}`));
  expect(Object.keys(titleCleanup(proposal, item.draft.tracks))).toHaveLength(44);
  // The 20th title (2.05.) mistyped as a second 2.04.: that row repeats a position and the next one skips, the rest stay clean.
  const typo = { ...item, source: { ...item.source, tracks: item.source.tracks.map((track, index) => index === 19 ? { ...track, title: '2.04.Synthetic long song 20' } : track) } };
  const stopped = titleProposal(typo.source.tracks, typo.draft.tracks);
  expect([stopped.accepted, stopped.count]).toEqual([false, 0]);
  expect(stopped.rows.flatMap((row, index) => row.flags.length ? [[index, row.flags]] : [])).toEqual([[19, ['duplicate']], [20, ['gap']]]);
});
